/**
 * The query classifier.
 *
 * Routing is per (model, domain), so every query must be assigned a domain before the sampler runs.
 * The classifier is a pure function from query features to a domain label. The default honors an
 * explicit `domain` and otherwise falls back to a single shared domain; a keyword classifier matches
 * query text against per-domain keyword lists; a static classifier pins every query to one domain.
 * Any custom function is accepted, so a consumer can plug in an embedding or model-based router.
 *
 * @packageDocumentation
 */

/** The domain used when nothing more specific is known. */
declare const DEFAULT_DOMAIN = "default";
/** Per-domain keyword lists. A query is assigned to the first domain whose keyword it contains. */
type KeywordRules = Readonly<Record<string, ReadonlyArray<string>>>;
/** The default classifier: return an explicit `domain` if present, otherwise {@link DEFAULT_DOMAIN}. */
declare function defaultClassifier(features: QueryFeatures): string;
/** A classifier that pins every query to a single fixed domain. */
declare function staticClassifier(domain: string): QueryClassifier;
/**
 * A classifier that matches the lowercased query text against per-domain keyword lists. An explicit
 * `domain` on the features always wins; otherwise the first domain with a matching keyword is used,
 * falling back to `fallback` when nothing matches.
 */
declare function keywordClassifier(rules: KeywordRules, fallback?: string): QueryClassifier;

export { DEFAULT_DOMAIN, type KeywordRules, QueryClassifier, QueryFeatures, defaultClassifier, keywordClassifier, staticClassifier };
